let fallbackCalls=0,fallbackHeaders=null;const fallbackResult=await postVisaCalJson({evaluate:async()=>{throw new TypeError('Failed to fetch')}},async(_url,options)=>{fallbackCalls++;fallbackHeaders=options.headers;return response({statusCode:1})},calApiUrl,{x:2},{browserHeaders:{Authorization:'browser-token'},nodeHeaders:{Authorization:'node-token','User-Agent':'native-browser'},stage:'Frames'});assert.equal(fallbackResult.transport,'node-fallback');assert.equal(fallbackCalls,1,'Cal performs exactly one bounded Node fallback only when the in-page request produced no HTTP response');assert.equal(fallbackHeaders.Accept,'application/json');assert.equal(fallbackHeaders.Authorization,'node-token');assert.equal(fallbackHeaders['User-Agent'],'native-browser');
await assert.rejects(()=>postVisaCalJson({evaluate:async()=>({status:200,body:'<html>Request Rejected</html>',retryAfter:''})},async()=>response({statusCode:1}),calApiUrl,{}, {stage:'Frames'}),error=>error.code==='CREDIT_PROVIDER_RESPONSE_NOT_JSON'&&error.transport==='browser','Cal HTML block pages are classified at the browser response boundary instead of surfacing an opaque JSON parse error');
