function fakeMaxScraperFixture({homeCards=[{Last4Digits:'4444',CreditLimit:10000,OpenToBuy:9000,CycleSummary:[{Date:'2026-09-10T00:00:00',CurrencySymbol:'₪'}]}],months={}}={}){
  const calls={initialize:0,login:0,terminate:0,requests:[]},page={evaluate:async(_fn,url)=>{calls.requests.push(url);let data;if(url.includes('/api/contents/getCategories'))data={result:[{id:7,name:'חו״ל'}]};else if(url.includes('/api/registered/getHomePageData'))data={Result:{UserCards:{Cards:homeCards}}};else{const parsed=new URL(url),filter=JSON.parse(parsed.searchParams.get('filterData')||'{}'),month=String(filter.date||'').replace(/-(\d)-01$/,'-0$1-01').slice(0,7);data=months[month]||{result:{transactions:[]}}}return {status:200,body:JSON.stringify(data),retryAfter:''}}};
  return {calls,scraper:{page,initialize:async()=>{calls.initialize++},login:async()=>{calls.login++;return {success:true}},terminate:async()=>{calls.terminate++}}};
}
